create extension if not exists btree_gist;
create schema adv;
create type adv."Mood" as enum ('very happy', 'it''s ok', 'SAD');
create type adv.pair as (a int[], b numeric(10,2));
create domain adv.tags as text[] check (cardinality(value) <= 5);
create sequence adv.down increment -2 minvalue -1000 maxvalue -1 start -1;
create table adv."Order Items" (
  "ID" bigint generated by default as identity primary key,
  "Weird Col" varchar(20)[] default '{}',
  amount numeric(12,4) not null default 0.0000,
  created timestamptz default (now() at time zone 'utc'),
  ttl interval default '1 day 02:00:00',
  mood adv."Mood" default 'it''s ok',
  label text collate "C",
  total numeric generated always as (amount * 2) stored,
  during tstzrange,
  constraint pos check (amount >= 0) not valid,
  exclude using gist (during with &&)
);
create unique index on adv."Order Items" (lower(label) desc nulls first) include (amount) where label is not null;
create table adv.parent (id int primary key, code text unique);
create table adv.child (id int primary key, pid int default 0 references adv.parent on delete set default on update cascade, code text references adv.parent(code) match full deferrable initially deferred);
create function adv.f(in a int, out b int, out c text) language sql immutable as $$ select a, a::text $$;
create function adv.v(variadic xs int[]) returns int language sql as $$ select array_length(xs, 1) $$;
create function adv.d(a int, b int default 5) returns int language plpgsql strict as $$ begin return a + b; end $$;
create function adv.t() returns table (x int, y text) language sql stable as $$ select 1, 'a' $$;
create function adv.trg() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger "Upd Trg" before update of amount, label on adv."Order Items" for each row when (old.amount is distinct from new.amount) execute function adv.trg();
alter table adv."Order Items" enable row level security;
create policy "Only Mine" on adv."Order Items" as restrictive for update to public using (label = current_user) with check (amount < 100);
comment on table adv."Order Items" is 'multi
line ''quoted'' comment';
comment on column adv."Order Items"."Weird Col" is 'col';
create materialized view adv.mv as select "ID", amount from adv."Order Items" with no data;
create unique index mv_id on adv.mv ("ID");
create view adv.vw as select "ID", amount from adv."Order Items" where amount > 0 with cascaded check option;
create type adv.floatr as range (subtype = float8, subtype_diff = float8mi);
create table adv.part (id int, region text, primary key (id, region)) partition by list (region);
create table adv.part_eu partition of adv.part for values in ('eu', 'uk');
create table adv.part_def partition of adv.part default;
create function adv.stmt_trg() returns trigger language plpgsql as $$ begin return null; end $$;
create trigger "Ref Trg" after update on adv.parent referencing old table as "Old Rows" new table as new_rows for each statement execute function adv.stmt_trg();
create trigger "Col Trg" after update of "Weird Col" on adv."Order Items" for each row execute function adv.trg();
create table adv."CamelCase" ("Id" int primary key, "parentId" int references adv."CamelCase" ("Id"), "Tags" adv.tags, p adv.pair, "x""y" text);
create index "Camel Idx" on adv."CamelCase" using gin ("Tags");
create index on adv."CamelCase" ("parentId") where "parentId" is not null;
alter table adv."CamelCase" add constraint "Uniq Pair" unique nulls not distinct ("parentId", "x""y");
create statistics adv."Camel Stats" (dependencies) on "Id", "parentId" from adv."CamelCase";
create rule "No Del" as on delete to adv."CamelCase" do instead nothing;
create view adv."Camel View" as select "Id", "x""y" from adv."CamelCase";
comment on column adv."Camel View"."x""y" is 'weird';
create function adv."Mixed Fn"("In Arg" int) returns int language sql immutable parallel safe cost 2 as $$ select "In Arg" $$;
create aggregate adv."Sum It"(int) (sfunc = int4pl, stype = int, initcond = '0');
create table adv.gen (a int, b int generated always as (a * 2) stored, c text generated always as (upper(adv."Mixed Fn"(a)::text)) stored);
create table adv.arr (a int[][] default '{{1,2},{3,4}}', b timestamp(3) without time zone default current_timestamp(3), c bit varying(8), d char(3) default 'ab', e numeric default -1.5, f double precision default 'NaN', g jsonb default '{"k": [1, 2]}'::jsonb, h boolean default (1 > 0));
